#!/usr/bin/env python3
"""Step164 worker/orchestration source-contract checks."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
W=(ROOT/'app/src/main/java/vn/kholinhkien/WeeklyBackupWorker.kt').read_text()
BACK=(ROOT/'app/src/main/java/vn/kholinhkien/BackupManager.kt').read_text()
UP=(ROOT/'app/src/main/java/vn/kholinhkien/SupabaseWeeklyBackupUploader.kt').read_text()
SYNC=(ROOT/'app/src/main/java/vn/kholinhkien/SyncWork.kt').read_text()
checks=[]
def ck(n, ok): checks.append((n,bool(ok)))
ck('worker validates owner UUID before touching database', 'isCanonicalOwnerId(ownerId)' in W)
ck('worker requires authenticated Supabase user to match scheduled owner', 'authenticatedId != ownerId' in W)
ck('worker reloads active profile and rejects inactive/password-change state', 'AuthRepository().getCurrentProfile()' in W and 'profile.mustChangePassword' in W and 'profile.isActive' in W)
ck('worker recovers local journal before preparing/uploading', 'WeeklyBackupRecovery.recoverOwner(applicationContext, dao, ownerId)' in W)
ck('worker reuses active backupId on retries', 'dao.activeWeeklyBackup(ownerId)' in W and 'WeeklyBackupLifecycle.backupIdForAttempt(' in W and 'return active.backupId' in (ROOT / 'app/src/main/java/vn/kholinhkien/WeeklyBackupLifecycle.kt').read_text())
ck('new backupId is generated only when no active journal exists', 'UUID.randomUUID().toString()' in W)
ck('worker passes same backupId through prepare and upload', 'backupId = backupId' in W and 'uploadAndVerify(prepared, backupId)' in W)
ck('worker uses authenticated profile username rather than input payload', 'username = profile.username' in W and 'inputData.getString("username")' not in W)
ck('worker does not bypass durable archive preparation', 'BackupManager.prepareWeeklyCloudBackup' in W)
ck('worker delegates upload to existing verified uploader', 'SupabaseWeeklyBackupUploader(applicationContext, client, dao)' in W)
ck('worker propagates cancellation instead of converting it to retry/success', 'catch (cancelled: CancellationException)' in W and 'throw cancelled' in W)
ck('transient exceptions request WorkManager retry', 'catch (_: Exception)' in W and 'Result.retry()' in W)
ck('account switch before and after profile/prepare exits without cross-account work', W.count('client.auth.currentUserOrNull()?.id != ownerId') >= 2 and 'authenticatedId != ownerId' in W)
ck('weekly work requires connected network', 'setRequiredNetworkType(NetworkType.CONNECTED)' in W)
ck('periodic backup interval is thirty days', 'PERIODIC_INTERVAL_DAYS = 30L' in W and 'TimeUnit.DAYS' in W)
ck('existing periodic work is updated when interval changes', 'ExistingPeriodicWorkPolicy.UPDATE' in W)
ck('unique periodic work prevents duplicate schedules per owner', 'enqueueUniquePeriodicWork' in W and 'uniqueName(ownerId)' in W)
ck('existing periodic schedule is updated idempotently without duplicate owner work', 'ExistingPeriodicWorkPolicy.UPDATE' in W and 'enqueueUniquePeriodicWork' in W)
ck('scheduler can cancel only the exact owner unique work', 'cancelUniqueWork(uniqueName(ownerId))' in W)
ck('worker scheduler is activated from validated app profile lifecycle', 'WeeklyBackupWorkScheduler.schedule(context, profile.id)' in (ROOT/'app/src/main/java/vn/kholinhkien/MainActivity.kt').read_text() and 'WeeklyBackupWorkScheduler.schedule' not in SYNC)
ck('worker reuses uploader immutable TUS archive validation', 'journal.archivePath != prepared.archive.canonicalPath' in UP and 'createOrContinueUpload(expectedPath, prepared.archive)' in UP)
ck('no new Room migration or schema mutation', '@Database(' in (ROOT/'app/src/main/java/vn/kholinhkien/Data.kt').read_text() and 'version = 14' in (ROOT/'app/src/main/java/vn/kholinhkien/Data.kt').read_text())
ck('no Gradle execution/dependency changes requested', 'gradle' not in W.lower())
for n,ok in checks: print(f'{"PASS" if ok else "FAIL"}: {n}')
print(f'RESULT: {sum(v for _,v in checks)}/{len(checks)} PASS')
raise SystemExit(0 if all(v for _,v in checks) else 1)
